begin;
set local lock_timeout='3s';
set local statement_timeout='60s';
insert into public.tenant_modules(tenant_id,module_id,enabled)
select '170d2d86-5c22-4bcb-9d74-420c879419b2', m,true from unnest(array['audit_security','payroll_hr','employees','suppliers','purchasing','vendor_portal','inventory','finance']) m
on conflict(tenant_id,module_id) do update set enabled=true;
-- Prevent any test event from running demo automations or queuing external delivery.
update public.tenant_modules set enabled=false where tenant_id='170d2d86-5c22-4bcb-9d74-420c879419b2' and module_id in ('workflow_automation','integrations','notifications');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"129bbbae-fdfc-4d21-8a86-8949fec2403b","role":"authenticated","app_metadata":{"tenant_id":"170d2d86-5c22-4bcb-9d74-420c879419b2","role":"owner"}}',true);
do $verify$
declare v_emp uuid; v_type uuid; v_leave public.leave_requests; v_run public.payroll_runs;
v_supplier uuid; v_other uuid; v_warehouse uuid; v_item uuid; v_po public.purchase_orders; v_line uuid;
v_link public.supplier_portal_access; v_view jsonb; v_ack jsonb; v_receipt public.purchase_receipts; v_bill public.vendor_bills; v_payment uuid; v_entry uuid;
begin
perform public.save_security_settings(30,true,null);
if ((select session_idle_minutes=30 and require_strong_passwords from public.security_settings)) is not true then raise exception 'VERIFY FAILED: security settings saved'; end if;
if (public.security_posture() ? 'members') is not true then raise exception 'VERIFY FAILED: security posture works'; end if;
if (exists(select 1 from public.security_members() where id=auth.uid())) is not true then raise exception 'VERIFY FAILED: security members scoped'; end if;
if (exists(select 1 from public.audit_tables() where audit_tables='security_settings')) is not true then raise exception 'VERIFY FAILED: settings audit recorded'; end if;
begin perform public.save_security_settings(1,false,null); raise exception 'VERIFY FAILED: invalid idle interval rejected'; exception when others then if sqlerrm not like 'SECURITY_INVALID_SETTING%' then raise; end if; end;
begin perform public.revoke_member_sessions(auth.uid()); raise exception 'VERIFY FAILED: self session revocation rejected'; exception when others then if sqlerrm not like 'CANNOT_SIGN_OUT_SELF%' then raise; end if; end;
perform public.hr_seed(array[5,6]);
perform public.save_hr_settings(array[5,6],8,1.5,0,0,true);
insert into public.employees(first_name,last_name,basic_salary,hire_date) values ('MigrationVerification','RollbackOnly',3000,'2020-01-01') returning id into v_emp;
select id into v_type from public.leave_types where code='annual';
v_leave:=public.request_leave(v_emp,v_type,'2026-10-18','2026-10-22','Temporary migration verification');
if (v_leave.days=5 and v_leave.status='pending') is not true then raise exception 'VERIFY FAILED: leave working days calculated'; end if;
v_leave:=public.leave_transition(v_leave.id,'approved','Verification');
if (v_leave.status='approved') is not true then raise exception 'VERIFY FAILED: leave approval works'; end if;
begin perform public.request_leave(v_emp,v_type,'2026-10-19','2026-10-20',null); raise exception 'VERIFY FAILED: overlapping leave rejected'; exception when others then if sqlerrm not like 'LEAVE_OVERLAP%' then raise; end if; end;
perform public.attendance_set('2026-10-14',jsonb_build_array(jsonb_build_object('employee_id',v_emp,'status','present','check_in','08:00','check_out','18:00')));
if ((select hours=10 from public.attendance_records where employee_id=v_emp and work_date='2026-10-14')) is not true then raise exception 'VERIFY FAILED: attendance hours calculated'; end if;
insert into public.payroll_runs(period_start,period_end) values ('2026-10-01','2026-10-31') returning * into v_run;
v_run:=public.payroll_calculate(v_run.id);
if (v_run.status='calculated' and v_run.employee_count>=1) is not true then raise exception 'VERIFY FAILED: payroll calculation works'; end if;
if (exists(select 1 from public.payslips where run_id=v_run.id and employee_id=v_emp and basic=3000 and overtime_hours=2 and net=3037.50)) is not true then raise exception 'VERIFY FAILED: payslip amount and overtime correct'; end if;
v_run:=public.payroll_approve(v_run.id);
if (v_run.status='approved') is not true then raise exception 'VERIFY FAILED: payroll approval works'; end if;
v_run:=public.payroll_mark_paid(v_run.id,'2026-10-31');
if (v_run.status='paid') is not true then raise exception 'VERIFY FAILED: payroll paid transition works'; end if;
begin update public.payroll_runs set notes='invalid edit' where id=v_run.id; raise exception 'VERIFY FAILED: paid payroll locked'; exception when others then if sqlerrm not like 'DOC_LOCKED%' then raise; end if; end;
insert into public.suppliers(name) values ('MigrationVerification RollbackOnly') returning id into v_supplier;
insert into public.suppliers(name) values ('MigrationVerification OtherSupplier') returning id into v_other;
insert into public.warehouses(name,code) values ('MigrationVerification','VERIFY-'||substr(gen_random_uuid()::text,1,8)) returning id into v_warehouse;
insert into public.inventory_items(name,sku) values ('MigrationVerification','VERIFY-'||gen_random_uuid()) returning id into v_item;
insert into public.purchase_orders(supplier_id,warehouse_id) values(v_supplier,v_warehouse) returning * into v_po;
insert into public.purchase_order_lines(purchase_order_id,item_id,description,quantity,unit_price,tax_rate) values(v_po.id,v_item,'Verification item',2,50,0) returning id into v_line;
if ((select total=100 and doc_number like 'PO-%' from public.purchase_orders where id=v_po.id)) is not true then raise exception 'VERIFY FAILED: purchase totals and numbering correct'; end if;
insert into public.supplier_portal_access(supplier_id,label) values(v_supplier,'Temporary verification') returning * into v_link;
set local role service_role;
v_view:=public.vendor_portal_view(v_link.token);
if (jsonb_array_length(v_view->'orders')=0) is not true then raise exception 'VERIFY FAILED: vendor portal hides drafts'; end if;
set local role authenticated; update public.purchase_orders set status='sent' where id=v_po.id;
set local role service_role; v_view:=public.vendor_portal_view(v_link.token);
if (jsonb_array_length(v_view->'orders')=1 and v_view->'orders'->0->>'id'=v_po.id::text) is not true then raise exception 'VERIFY FAILED: vendor portal shows sent order'; end if;
if (not (v_view->'orders'->0 ? 'notes') and not (v_view->'supplier' ? 'iban')) is not true then raise exception 'VERIFY FAILED: vendor portal whitelists data'; end if;
v_ack:=public.vendor_portal_acknowledge(v_link.token,v_po.id,current_date+7,'Verification acknowledgement');
if (v_ack->>'status'='confirmed') is not true then raise exception 'VERIFY FAILED: vendor acknowledgement confirms order'; end if;
begin perform public.vendor_portal_acknowledge(v_link.token,v_po.id,null,null); raise exception 'VERIFY FAILED: duplicate acknowledgement rejected'; exception when others then if sqlerrm not like 'PO_NOT_ACKNOWLEDGEABLE%' then raise; end if; end;
set local role authenticated;
v_receipt:=public.purchase_receive(v_po.id,jsonb_build_array(jsonb_build_object('line_id',v_line,'quantity',2)),v_warehouse,'Verification');
if (v_receipt.doc_number like 'GRN-%') is not true then raise exception 'VERIFY FAILED: goods receipt numbered'; end if;
if ((select status='received' from public.purchase_orders where id=v_po.id)) is not true then raise exception 'VERIFY FAILED: purchase fully received'; end if;
if ((select on_hand=2 from public.stock_levels where item_id=v_item and warehouse_id=v_warehouse)) is not true then raise exception 'VERIFY FAILED: receipt updates inventory'; end if;
v_bill:=public.vendor_bill_from_po(v_po.id);
if (v_bill.total=100 and v_bill.status='draft') is not true then raise exception 'VERIFY FAILED: vendor bill created from receipt'; end if;
update public.vendor_bills set status='open' where id=v_bill.id;
insert into public.vendor_payments(vendor_bill_id,amount) values(v_bill.id,100) returning id into v_payment;
if ((select status='paid' and amount_paid=100 from public.vendor_bills where id=v_bill.id)) is not true then raise exception 'VERIFY FAILED: vendor payment settles bill'; end if;
perform public.finance_setup();
v_entry:=public.finance_post_vendor_bill(v_bill.id);
if (v_entry is not null) is not true then raise exception 'VERIFY FAILED: finance posts vendor bill'; end if;
v_entry:=public.finance_post_vendor_payment(v_payment);
if (v_entry is not null) is not true then raise exception 'VERIFY FAILED: finance posts vendor payment'; end if;
v_entry:=public.finance_post_payroll(v_run.id);
if (v_entry is not null) is not true then raise exception 'VERIFY FAILED: finance posts payroll'; end if;
begin perform public.vendor_portal_view(v_link.token); raise exception 'VERIFY FAILED: authenticated denied service-only vendor RPC'; exception when others then if sqlerrm not like 'permission denied%' then raise; end if; end;
update public.supplier_portal_access set active=false where id=v_link.id;
set local role service_role;
if (public.vendor_portal_view(v_link.token) is null) is not true then raise exception 'VERIFY FAILED: revoked vendor link rejected'; end if;
set local role authenticated;
perform set_config('request.jwt.claims','{"sub":"129bbbae-fdfc-4d21-8a86-8949fec2403b","role":"authenticated","app_metadata":{"tenant_id":"170d2d86-5c22-4bcb-9d74-420c879419b2","role":"viewer"}}',true);
begin perform public.security_posture(); raise exception 'VERIFY FAILED: viewer denied admin security RPC'; exception when others then if sqlerrm not like 'FORBIDDEN%' then raise; end if; end;
begin perform public.save_hr_settings(array[5,6],8,1.5,0,0,true); raise exception 'VERIFY FAILED: viewer denied HR settings'; exception when others then if sqlerrm not like 'FORBIDDEN%' then raise; end if; end;
if (not exists(select 1 from public.supplier_portal_access)) is not true then raise exception 'VERIFY FAILED: viewer cannot see vendor tokens'; end if;
if (not exists(select 1 from public.payroll_runs)) is not true then raise exception 'VERIFY FAILED: viewer cannot see payroll runs'; end if;
perform set_config('request.jwt.claims',jsonb_build_object('sub',auth.uid(),'role','authenticated','app_metadata',jsonb_build_object('tenant_id',gen_random_uuid(),'role','owner'))::text,true);
if (not exists(select 1 from public.purchase_orders where id=v_po.id)) is not true then raise exception 'VERIFY FAILED: other tenant cannot read purchase'; end if;
if (not exists(select 1 from public.payslips where run_id=v_run.id)) is not true then raise exception 'VERIFY FAILED: other tenant cannot read payslips'; end if;
end $verify$;
rollback;
select '37 production workflow assertions passed; all test writes rolled back' as result;
